// TypeScript Version: 4.1

/**
* Interface describing `dlasq5`.
*/
interface Routine {
	/**
	* Computes one DQDS transform in ping-pong form.
	*
	* ## Notes
	*
	* -   `Z` is a 1-D array of length >= `4*N0` storing interleaved q/e values.
	* -   `PP` is `0` for ping, `1` for pong.
	*
	* @param I0 - the first index
	* @param N0 - the last index
	* @param Z - the QD array
	* @param PP - ping-pong flag (0 or 1)
	* @param TAU - the shift
	* @param SIGMA - the accumulated shift
	* @param IEEE - IEEE arithmetic flag
	* @param EPS - epsilon
	* @param out - output array containing `DMIN`, `DMIN1`, `DMIN2`, `DN`, `DNM1`, and `DNM2` respectively
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var dlasq5 = require( '@stdlib/lapack/base/dlasq5' );
	*
	* var out = new Float64Array( 6 );
	* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
	*
	* dlasq5( 0, 3, Z, 0, 0.1, 0.0, true, 2.220446049250313e-16, out );
	* // out => <Float64Array>[ ~3.606, ~3.606, ~3.606, ~11.823, ~5.904, ~3.606 ]
	*/
	( I0: number, N0: number, Z: Float64Array, PP: boolean, TAU: number, SIGMA: number, IEEE: boolean, EPS: number, out: Float64Array ): Float64Array;

	/**
	* Computes one DQDS transform in ping-pong form using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `Z` is a 1-D array of length >= `4*N0` storing interleaved q/e values.
	* -   `PP` is `0` for ping, `1` for pong.
	*
	* @param I0 - the first index
	* @param N0 - the last index
	* @param Z - the QD array
	* @param strideZ - stride length for `Z`
	* @param offsetZ - starting index for `Z`
	* @param PP - ping-pong flag (0 or 1)
	* @param TAU - the shift
	* @param SIGMA - the accumulated shift
	* @param IEEE - IEEE arithmetic flag
	* @param EPS - epsilon
	* @param out - output array containing `DMIN`, `DMIN1`, `DMIN2`, `DN`, `DNM1`, and `DNM2` respectively
	* @param strideOut - stride length for `out`
	* @param offsetOut - starting index of `out`
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var dlasq5 = require( '@stdlib/lapack/base/dlasq5' );
	*
	* var out = new Float64Array( 6 );
	* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
	*
	* dlasq5.ndarray( 0, 3, Z, 1, 0, 0, 0.1, 0.0, true, 2.220446049250313e-16, out, 1, 0 );
	* // out => <Float64Array>[ ~3.606, ~3.606, ~3.606, ~11.823, ~5.904, ~3.606 ]
	*/
	ndarray( I0: number, N0: number, Z: Float64Array, strideZ: number, offsetZ: number, PP: boolean, TAU: number, SIGMA: number, IEEE: boolean, EPS: number, out: Float64Array, strideOut: number, offsetOut: number ): Float64Array;
}

/**
* LAPACK routine to compute one DQDS transform in ping-pong form.
*
* ## Notes
*
* -   `Z` is a 1-D array of length >= `4*N0` storing interleaved q/e values.
* -   `PP` is `0` for ping, `1` for pong.
*
* @param I0 - the first index
* @param N0 - the last index
* @param Z - the QD array
* @param PP - ping-pong flag (0 or 1)
* @param TAU - the shift
* @param SIGMA - the accumulated shift
* @param IEEE - IEEE arithmetic flag
* @param EPS - epsilon
* @param out - output array containing `DMIN`, `DMIN1`, `DMIN2`, `DN`, `DNM1`, and `DNM2` respectively
* @returns output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasq5 = require( '@stdlib/lapack/base/dlasq5' );
*
* var out = new Float64Array( 6 );
* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
*
* dlasq5( 0, 3, Z, 0, 0.1, 0.0, true, 2.220446049250313e-16, out );
* // out => <Float64Array>[ ~3.606, ~3.606, ~3.606, ~11.823, ~5.904, ~3.606 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasq5 = require( '@stdlib/lapack/base/dlasq5' );
*
* var out = new Float64Array( 6 );
* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
*
* dlasq5.ndarray( 0, 3, Z, 1, 0, 0, 0.1, 0.0, true, 2.220446049250313e-16, out, 1, 0 );
* // out => <Float64Array>[ ~3.606, ~3.606, ~3.606, ~11.823, ~5.904, ~3.606 ]
*/
declare var dlasq5: Routine;


// EXPORTS //

export = dlasq5;
